def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (everything after '+')
        if '+' in version:
            version_part, _ = version.split('+', 1)
        else:
            version_part = version

        # Split pre-release (everything after '-')
        if '-' in version_part:
            base_part, prerelease_str = version_part.split('-', 1)
            prerelease = prerelease_str.split('.')
        else:
            base_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are either None or a list of identifiers
        # A version without pre-release has higher precedence than with pre-release
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release is greater
        if pre2 is None:
            return -1  # version with pre-release is less

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all-digit
            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric - compare numerically
                val1 = int(id1)
                val2 = int(id2)
                if val1 < val2:
                    return -1
                elif val1 > val2:
                    return 1
            elif is_num1:
                # id1 is numeric, id2 is not - numeric comes first
                return -1
            elif is_num2:
                # id2 is numeric, id1 is not
                return 1
            else:
                # Both non-numeric - compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1

        return 0

    def sort_key(version):
        major, minor, patch, prerelease = parse_version(version)
        # Return tuple: (major, minor, patch, prerelease_sort_key)
        # For prerelease, we need a tuple that sorts correctly
        if prerelease is None:
            # No prerelease - should sort after same version with prerelease
            prerelease_key = (1,)  # This will sort after (0, ...)
        else:
            # Has prerelease - create a comparable key
            prerelease_key = (0,) + tuple(
                (0, int(id)) if id.isdigit() else (1, id)
                for id in prerelease
            )

        return (major, minor, patch, prerelease_key)

    # Use stable sort to maintain input order for equal versions
    return sorted(versions, key=sort_key)

